(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("horace-epistles-b", [{"sp": "HDR", "t": "Epistulae"}, {"sp": "HDR", "t": "Liber I", "st": "1"}, {"sp": "SEC", "t": "I", "st": "1.1"}, {"sp": "N", "t": "Prima dicte mihi, summa dicende Camena,<br>spectatum satis et donatum iam rude quaeris,<br>Maecenas, iterum antiquo me includere ludo.<br>non eadem est aetas, non mens. Veianius armis<br>Herculis ad postem fixis latet abditus agro,<br>ne populum extrema totiens exoret harena,<br>est mihi purgatam crebro qui personet aurem:<br>“solve senescentem mature sanus equum, ne<br>peccet ad extremum ridendus et ilia ducat.”<br>Nunc itaque et versus et cetera ludicra pono;<br>quid verum atque decens curo et rogo et omnis in hoc sum;<br>condo et compono quae mox depromere possim.<br>ac ne forte roges, quo me duce, quo lare tuter:<br>nullius addictus iurare in verba magistri,<br>quo me cumque rapit tempestas, deferor hospes.<br>nunc agilis fio et mersor civilibus undis,<br>virtutis verae custos rigidusque satelles;<br>nunc in Aristippi furtim praecepta relabor<br>et mihi res, non me rebus, subiungere conor.", "st": "1.1"}, {"sp": "N", "t": "Ut nox longa quibus mentitur amica, diesque<br>longa videtur opus debentibus, ut piger annus<br>pupillis, quos dura premit custodia matrum;<br>sic mihi tarda fluunt ingrataque tempora, quae spem<br>consiliumque morantur agendi naviter id quod<br>aeque pauperibus prodest, locupletibus aeque,<br>aeque neglectum pueris senibusque nocebit,<br>restat ut his ego me ipse regam solerque elementis,<br>non possis oculo quantum contendere Lynceus,<br>non tamen idcirco contemnas lippus inungui;<br>nec quia desperes invicti membra Glyconis,<br>nodosa corpus nolis prohibere cheragra.<br>est quadam prodire tenus, si non datur ultra.<br>Fervet avaritia miseroque cupidine pectus:<br>sunt verba et voces, quibus hunc lenire dolorem<br>possis et magnam morbi deponere partem.<br>laudis amore tumes; sunt certa piacula, quae te<br>ter pure lecto poterunt recreare libello.<br>invidus, iracundus, iners, vinosus, amator,<br>nemo adeo ferus est, ut non mitescere possit,<br>si modo culturae patientem commodet aurem.", "st": "1.1"}, {"sp": "N", "t": "Virtus est vitium fugere et sapientia prima<br>stultitia caruisse, vides, quae maxima credis<br>esse mala, exiguum censum turpemque repulsam,<br>quanto devites animi capitisque labore;<br>impiger extremos curris mercator ad Indos,<br>per mare pauperiem fugiens, per saxa, per ignis:<br>ne cures ea, quae stulte miraris et optas,<br>discere et audire et meliori credere non vis?<br>quis circum pagos et circum compita pugnax<br>magna coronari contemnat Olympia, cui spes,<br>cui sit condicio dulcis sine pulvere palmae?<br>Vilius argentum est auro, virtutibus aurum.<br>“o cives, cives, quaerenda pecunia primum est;<br>virtus post nummos!” haec Ianus summus ab imo<br>prodocet, haec recinunt iuvenes dictata senesque,<br>laevo suspensi loculos tabulamque lacerto.<br>est animus tibi, sunt mores, est lingua fidesque,<br>sed quadringentis sex septem milia desunt;<br>plebs eris. at pueri ludentes, “rex eris,” aiunt,<br>“si recte facies.” hic murus aeneus esto,<br>nil conscire sibi, nulla pallescere culpa.", "st": "1.1"}, {"sp": "N", "t": "Roscia, dic sodes, melior lex an puerorum est<br>nenia, quae regnum recte facientibus offert,<br>et maribus Curiis et decantata Camillis?<br>isne tibi melius suadet, qui “rem facias, rem,<br>si possis, recte, si non, quocumque modo, rem,”<br>ut propius spectes lacrimosa poemata Pupi,<br>an qui Fortunae te responsare superbae<br>liberum et erectum praesens hortatur et aptat?<br>Quod si me populus Romanus forte roget, cur<br>non ut porticibus sic iudiciis fruar isdem,<br>nec sequar aut fugiam quae diligit ipse vel odit,<br>olim quod volpes aegroto cauta leoni<br>respondit, referam: “quia me vestigia terrent,<br>omnia te adversum spectantia, nulla retrorsum.”<br>belua multorum es capitum, nam quid sequar aut quem?<br>pars hominum gestit conducere publica; sunt qui<br>frustis et pomis viduas venentur avaras<br>excipiantque senes, quos in vivaria mittant;<br>multis occulto crescit res faenore. Verum<br>esto aliis alios rebus studiisque teneri:<br>idem eadem possunt horam durare probantes?<br>“nullus in orbe sinus Bais praelucet amoenis,”<br>si dixit dives, lacus et mare sentit amorem<br>festinantis eri; cui si vitiosa libido<br>fecerit auspicium, “cras ferramenta Teanum<br>tolletis, fabri!” lectus genialis in aula est:<br>nil ait esse prius, melius nil caelibe vita;<br>si non est, iurat bene solis esse maritis.<br>quo teneam voltus mutantem Protea nodo?<br>quid pauper? ride: mutat cenacula, lectos,<br>balnea, tonsores, conducto navigio aeque<br>nauseat ac locuples, quem ducit priva triremis.", "st": "1.1"}, {"sp": "N", "t": "Si curatus inaequali tonsore capillos<br>occurri, rides; si forte subucula pexae<br>trita subest tunicae, vel si toga dissidet impar,<br>rides: quid, mea cum pugnat sententia secum,<br>quod petiit spernit, repetit quod nuper omisit,<br>aestuat et vitae disconvenit ordine toto,<br>diruit, aedificat, mutat quadrata rotundis?<br>insanire putas sollemnia me neque rides,<br>nec medici credis nec curatoris egere<br>a praetore dati, rerum tutela mearum<br>cum sis et prave sectum stomacheris ob unguem<br>de te pendentis, te respicientis amici.<br>Ad summam: sapiens uno minor est Iove, dives,<br>liber, honoratus, pulcher, rex denique regum,<br>praecipue sanus, nisi cum pituita molesta est.", "st": "1.1"}, {"sp": "SEC", "t": "II", "st": "1.2"}, {"sp": "N", "t": "Troiani belli scriptorem, Maxime Lolli,<br>dum tu declamas Romae, Praeneste relegi;<br>qui quid sit pulchrum, quid turpe, quid utile, quid non,<br>planius ac melius Chrysippo et Crantore dicit,<br>cur ita crediderim, nisi quid te distinet, audi.<br>Fabula, qua Paridis propter narratur amorem<br>Graecia barbariae lento collisa duello,<br>stultorum regum et populorum continet aestus.<br>Antenor censet belli praecidere causam:<br>quid Paris? ut salvus regnet vivatque beatus<br>cogi posse negat. Nestor componere litis<br>inter Peliden festinat et inter Atriden;<br>hunc amor, ira quidem communiter urit utrumque,<br>quidquid delirant reges, plectuntur Achivi.<br>seditione, dolis, scelere atque libidine et ira<br>Iliacos intra muros peccatur et extra.<br>Rursus, quid virtus et quid sapientia possit,<br>utile proposuit nobis exemplar Ulixen,<br>qui domitor Troiae multorum providus urbes<br>et mores hominum inspexit, latumque per aequor,<br>dum sibi, dum sociis reditum parat, aspera multa<br>pertulit, adversis rerum immersabilis undis.", "st": "1.2"}, {"sp": "N", "t": "Sirenum voces et Circae pocula nosti;<br>quae si cum sociis stultus cupidusque bibisset,<br>sub domina meretrice fuisset turpis et excors,<br>vixisset canis immundus vel amica luto sus.<br>nos numerus sumus et fruges consumere nati,<br>sponsi Penelopae nebulones, Alcinoique<br>in cute curanda plus aequo operata iuventus,<br>cui pulchrum fuit in medios dormire dies et<br>ad strepitum citharae cessatum ducere curam.<br>Ut iugulent hominem, surgunt de nocte latrones;<br>ut te ipsum serves, non expergisceris? atqui<br>si noles sanus, curres hydropicus; et ni<br>posces ante diem librum cum lumine, si non<br>intendes animum studiis et rebus honestis,<br>invidia vel amore vigil torquebere. nam cur<br>quae laedunt oculum festinas demere; si quid<br>est animum, differs curandi tempus in annum?<br>dimidium facti qui coepit habet; sapere aude;<br>incipe! qui recte vivendi prorogat horam,<br>rusticus exspectat dum defluat amnis; at ille<br>labitur et labetur in omne volubilis aevum<br>Quaeritur argentum puerisque beata creandis<br>uxor, et incultae pacantur vomere silvae:<br>quod satis est cui contingit, nihil amplius optet.<br>non domus et fundus, non aeris acervus et auri<br>aegroto domini deduxit corpore febris,<br>non animo curas; valeat possessor oportet,<br>si comportatis rebus bene cogitat uti.<br>qui cupit aut metuit, iuvat illum sic domus et res,<br>ut lippum pictae tabulae, fomenta podagram,<br>auriculas citharae collecta sorde dolentis.<br>sincerum est nisi vas, quodcumque infundis acescit.", "st": "1.2"}, {"sp": "N", "t": "Sperne voluptates; nocet empta dolore voluptas,<br>semper avarus eget; certum voto pete finem.<br>invidus alterius macrescit rebus opimis;<br>invidia Siculi non invenere tyranni<br>maius tormentum, qui non moderabitur irae,<br>infectum volet esse, dolor quod suaserit et mens,<br>dum poenas odio per vim festinat inulto,<br>ira furor brevis est: animum rege; qui nisi paret<br>imperat; hunc frenis, hunc tu compesce catena.<br>Fingit equum tenera docilem cervice magister<br>ire viam qua monstret eques; venaticus, ex quo<br>tempore cervinam pellem latravit in aula,<br>militat in silvis catulus, nunc adhibe puro<br>pectore verba puer, nunc te melioribus offer,<br>quo semel est imbuta recens, servabit odorem<br>testa diu. quod si cessas aut strenuus anteis,<br>nec tardum opperior nec praecedentibus insto.", "st": "1.2"}, {"sp": "SEC", "t": "III", "st": "1.3"}, {"sp": "N", "t": "Iuli Flore, quibus terrarum militet oris<br>Claudius Augusti privignus, scire laboro.<br>Thracane vos Hebrusque nivali compede vinctus,<br>an freta vicinas inter currentia turris,<br>an pingues Asiae campi collesque morantur?<br>Quid studiosa cohors operum struit? hoc quoque curo.<br>quis sibi res gestas Augusti scribere sumit?<br>bella quis et paces longum diffundit in aevum?<br>quid Titius, Romana brevi venturus in ora?<br>Pindarici fontis qui non expalluit haustus,<br>fastidire lacus et rivos ausus apertos,<br>ut valet? ut meminit nostri? fidibusne Latinis<br>Thebanos aptare modos studet auspice Musa,<br>an tragica desaevit et ampullatur in arte?<br>quid mihi Celsus agit? monitus multumque monendus,<br>privatas ut quaerat opes et tangere vitet<br>scripta Palatinus quaecumque recepit Apollo,<br>ne, si forte suas repetitum venerit olim<br>grex avium plumas, moveat cornicula risum<br>furtivis nudata coloribus, ipse quid audes?<br>quae circumvolitas agilis thyma? non tibi parvum<br>ingenium, non incultum est et turpiter hirtum.<br>seu linguam causis acuis seu civica iura<br>respondere paras seu condis amabile carmen,<br>prima feres hederae victricis praemia, quod si<br>frigida curarum fomenta relinquere posses,<br>quo te caelestis sapientia duceret, ires.<br>hoc opus, hoc studium parvi properemus et ampli,<br>si patriae volumus, si nobis vivere cari.<br>Debes hoc etiam rescribere, sit tibi curae<br>quantae conveniat Munatius; an male sarta<br>gratia nequiquam coit et rescinditur? at vos<br>seu calidus sanguis seu rerum inscitia vexat<br>indomita cervice feros, ubicumque locorum<br>vivitis, indigni fraternum rumpere foedus,<br>pascitur in vestrum reditum votiva iuvenca.", "st": "1.3"}, {"sp": "SEC", "t": "IV", "st": "1.4"}, {"sp": "N", "t": "Albi, nostrorum sermonum candide iudex,<br>quid nunc te dicam facere in regione Pedana?<br>scribere quod Cassi Parmensis opuscula vincat,<br>an tacitum silvas inter reptare salubris,<br>curantem quidquid dignum sapiente bonoque est?<br>non tu corpus eras sine pectore: di tibi formam,<br>di tibi divitias dederunt artemque fruendi.<br>quid voveat dulci nutricula maius alumno,<br>qui sapere et fari possit quae sentiat, et cui<br>gratia, fama, valetudo contingat abunde,<br>et mundus victus non deficiente crumina?<br>Inter spem curamque, timores inter et iras<br>omnem crede diem tibi diluxisse supremum,<br>grata superveniet, quae non sperabitur hora.<br>me pinguem et nitidum bene curata cute vises,<br>cum ridere voles, Epicuri de grege porcum.", "st": "1.4"}, {"sp": "SEC", "t": "V", "st": "1.5"}, {"sp": "N", "t": "Si potes Archiacis conviva recumbere lectis<br>nec modica cenare times holus omne patella,<br>supremo te sole domi, Torquate, manebo,<br>vina bibes iterum Tauro diffusa palustris<br>inter Minturnas Sinuessanumque Petrinum.<br>si melius quid habes, arcesse, vel imperium fer.<br>iamdudum splendet focus et tibi munda supellex,<br>mitte levis spes et certamina divitiarum<br>et Moschi causam: cras nato Caesare festus<br>dat veniam somnumque dies; impune licebit<br>aestivam sermone benigno tendere noctem.<br>Quo mihi fortunam, si non conceditur uti?<br>parcus ob heredis curam nimiumque severus<br>adsidet insano, potare et spargere flores<br>incipiam, patiarque vel inconsultus haberi.<br>quid non ebrietas dissignat? operta recludit,<br>spes iubet esse ratas, ad proelia trudit inertem,<br>sollicitis animis onus eximit, addocet artes.<br>fecundi calices quem non fecere disertum?<br>contracta quem non in paupertate solutum?<br>Haec ego procurare et idoneus imperor et non<br>invitus, ne turpe toral, ne sordida mappa<br>corruget naris, ne non et cantharus et lanx<br>ostendat tibi te, ne fidos inter amicos<br>sit qui dicta foras eliminet, ut coeat par<br>iungaturque pari. Butram tibi Septiciumque,<br>et nisi cena prior potiorque puella Sabinum<br>detinet, adsumam. locus est et pluribus umbris:<br>sed nimis arta premunt olidae convivia caprae,<br>tu quotus esse velis rescribe et rebus omissis<br>atria servantem postico falle clientem.", "st": "1.5"}, {"sp": "SEC", "t": "VI", "st": "1.6"}, {"sp": "N", "t": "Nil admirari prope res est una, Numici,<br>solaque quae possit facere et servare beatum,<br>hunc solem et stellas et decedentia certis<br>tempora momentis sunt qui formidine nulla<br>imbuti spectent: quid censes munera terrae,<br>quid maris extremos Arabas ditantis et Indos,<br>ludicra quid, plausus et amici dona Quiritis,<br>quo spectanda modo, quo sensu credis et ore?<br>Qui timet his adversa, fere miratur eodem<br>quo cupiens pacto: pavor est utrobique molestus,<br>improvisa simul species exterret utrumque.<br>gaudeat an doleat, cupiat metuatne, quid ad rem,<br>si, quicquid vidit melius peiusve sua spe,<br>defixis oculis animoque et corpore torpet?<br>insani sapiens nomen ferat, aequus iniqui,<br>ultra quam satis est Virtutem si petat ipsam.<br>I nunc, argentum et marmor vetus aeraque et artes<br>suspice, cum gemmis Tyrios mirare colores;<br>gaude quod spectant oculi te mille loquentem;<br>navus mane forum et vespertinus pete tectum,<br>ne plus frumenti dotalibus emetat agris<br>Mutus et (indignum, quod sit peioribus ortus)<br>hic tibi sit potius quam tu mirabilis illi.<br>quidquid sub terra est, in apricum proferet aetas,<br>defodiet condetque nitentia, cum bene notum<br>porticus Agrippae, via te conspexerit Appi,<br>ire tamen restat Numa quo devenit et Ancus.", "st": "1.6"}, {"sp": "N", "t": "Si latus aut renes morbo temptantur acuto,<br>quaere fugam morbi, vis recte vivere: quis non?<br>si Virtus hoc una potest dare, fortis omissis<br>hoc age deliciis. Virtutem verba putas et<br>lucum ligna: cave ne portus occupet alter,<br>ne Cibyratica, ne Bithyna negotia perdas;<br>mille talenta rotundentur, totidem altera, porro et<br>tertia succedant et quae pars quadret acervum.<br>scilicet uxorem cum dote fidemque et amicos<br>et genus et formam regina Pecunia donat,<br>ac bene nummatum decorat Suadela Venusque,<br>mancupiis locuples eget aeris Cappadocum rex:<br>ne fueris hic tu. chlamydes Lucullus, ut aiunt,<br>si posset centum scaenae praebere rogatus,<br>“qui possum tot?” ait; “tamen et quaeram et quot habebo<br>mittam:” post paulo scribit sibi milia quinque<br>esse domi chlamydum; partem vel tolleret omnis,<br>exilis domus est, ubi non et multa supersunt<br>et dominum fallunt et prosunt furibus. ergo<br>si res sola potest facere et servare beatum,<br>hoc primus repetas opus, hoc postremus omittas.<br>Si fortunatum species et gratia praestat,<br>mercemur servum, qui dictet nomina, laevum<br>qui fodicet latus et cogat trans pondera dextram<br>porrigere: “hic multum in Fabia valet, ille Velina;<br>cui libet hic fasces dabit eripietque curule<br>cui volet importunus ebur.” “frater,” “pater” adde:<br>ut cuique est aetas, ita quemque facetus adopta.", "st": "1.6"}, {"sp": "N", "t": "Si bene qui cenat bene vivit, lucet, eamus<br>quo ducit gula; piscemur, venemur, ut olim<br>Gargilius, qui mane plagas, venabula, servos<br>differtum transire forum populumque iubebat,<br>unus ut e multis populo spectante referret<br>emptum mulus aprum, crudi tumidique lavemur,<br>quid deceat, quid non, obliti, Caerite cera<br>digni, remigium vitiosum Ithacensis Ulixei,<br>cui potior patria fuit interdicta voluptas.<br>si, Mimnermus uti censet, sine amore iocisque<br>nil est iucundum, vivas in amore iocisque.<br>Vive, vale! si quid novisti rectius istis,<br>candidus imperti; si nil, his utere mecum.", "st": "1.6"}, {"sp": "SEC", "t": "VII", "st": "1.7"}, {"sp": "N", "t": "Quinque dies tibi pollicitus me rure futurum,<br>Sextilem totum mendax desideror. atque<br>si me vivere vis sanum recteque valentem,<br>quam mihi das aegro, dabis aegrotare timenti,<br>Maecenas, veniam, dum ficus prima calorque<br>dissignatorem decorat lictoribus atris,<br>dum pueris omnis pater et matercula pallet,<br>officiosaque sedulitas et opella forensis<br>adducit febris et testamenta resignat.<br>quod si bruma nives Albanis illinet agris,<br>ad mare descendet vates tuus et sibi parcet<br>contractusque leget; te, dulcis amice, reviset<br>cum Zephyris, si concedes, et hirundine prima.<br>Non quo more piris vesci Calaber iubet hospes,<br>tu me fecisti locupletem. “vescere, sodes.”<br>“iam satis est.” “at tu quantum vis tolle.” “benigne.”<br>“non invisa feres pueris munuscula parvis.”<br>“tam teneor dono, quam si dimittar onustus.”<br>“ut libet; haec porcis hodie comedenda relinques.”<br>prodigus et stultus donat quae spernit et odit;<br>haec seges ingratos tulit et feret omnibus annis,<br>vir bonus et sapiens dignis ait esse paratus,<br>nec tamen ignorat quid distent aera lupinis.<br>dignum praestabo me etiam pro laude merentis.<br>quod si me noles usquam discedere, reddes<br>forte latus, nigros angusta fronte capillos,<br>reddes dulce loqui, reddes ridere decorum et<br>inter vina fugam Cinarae maerere protervae.", "st": "1.7"}, {"sp": "N", "t": "Forte per angustam tenuis volpecula rimam<br>repserat in cumeram frumenti, pastaque rursus<br>ire foras pleno tendebat corpore frustra;<br>cui mustela procul, “si vis,” ait, “effugere istinc,<br>macra cavum repetes artum, quem macra subisti.”<br>hac ego si compellor imagine, cuncta resigno;<br>nec somnum plebis laudo satur altilium nec<br>otia divitiis Arabum liberrima muto.<br>saepe verecundum laudasti, rexque paterque<br>audisti coram nec verbo parcius absens:<br>inspice si possum donata reponere laetus.<br>haud male Telemachus, proles patientis Ulixei:<br>“non est aptus equis Ithace locus, ut neque planis<br>porrectus spatiis nec multae prodigus herbae:<br>Atride, magis apta tibi tua dona relinquam.”<br>parvum parva decent: mihi iam non regia Roma,<br>sed vacuum Tibur placet aut imbelle Tarentum.<br>Strenuus et fortis causisque Philippus agendis<br>clarus, ab officiis octavam circiter horam<br>dum redit atque Foro nimium distare Carinas<br>iam grandis natu queritur, conspexit, ut aiunt,<br>adrasum quendam vacua tonsoris in umbra<br>cultello proprios purgantem leniter unguis.", "st": "1.7"}, {"sp": "N", "t": "“Demetri,” (puer hic non laeve iussa Philippi<br>accipiebat) “abi, quaere et refer, unde domo, quis,<br>cuius fortunae, quo sit patre quove patrono.”<br>it, redit et narrat, Volteium nomine Menam,<br>praeconem, tenui censu, sine crimine, notum<br>et properare loco et cessare et quaerere et uti,<br>gaudentem parvisque sodalibus et lare certo<br>et ludis et post decisa negotia Campo.<br>“scitari libet ex ipso quodcumque refers: dic<br>ad cenam veniat.” non sane credere Mena,<br>mirari secum tacitus, quid multa? “benigne,”<br>respondet. “neget ille mihi?” “negat improbus et te<br>neglegit aut horret.” Volteium mane Philippus<br>vilia vendentem tunicato scruta popello<br>occupat et salvere iubet prior, ille Philippo<br>excusare laborem et mercennaria vincla,<br>quod non mane domum venisset, denique quod non<br>providisset eum. “sic ignovisse putato<br>me tibi, si cenas hodie mecum.” “ut libet.” “ergo<br>post nonam venies: nunc i, rem strenuus auge.”", "st": "1.7"}, {"sp": "N", "t": "ut ventum ad cenam est, dicenda tacenda locutus<br>tandem dormitum dimittitur. Hic ubi saepe<br>occultum visus decurrere piscis ad hamum,<br>mane cliens et iam certus conviva, iubetur<br>rura suburbana indictis comes ire Latinis,<br>impositus mannis arvum caelumque Sabinum<br>non cessat laudare, videt ridetque Philippus,<br>et sibi dum requiem, dum risus undique quaerit,<br>dum septem donat sestertia, mutua septem<br>promittit, persuadet uti mercetur agellum.<br>mercatur. ne te longis ambagibus ultra<br>quam satis est morer, ex nitido fit rusticus atque<br>sulcos et vineta crepat mera, praeparat ulmos,<br>immoritur studiis et amore senescit habendi.<br>verum ubi oves furto, morbo periere capellae,<br>spem mentita seges, bos est enectus arando,<br>offensus damnis media de nocte caballum<br>arripit iratusque Philippi tendit ad aedis.<br>quem simul aspexit scabrum intonsumque Philippus,<br>“durus,” ait, “Voltei, nimis attentusque videris<br>esse mihi.” “pol, me miserum, patrone, vocares,<br>si velles,” inquit, “verum mihi ponere nomen.<br>quod te per Genium dextramque deosque Penatis<br>obsecro et obtestor, vitae me redde priori!”<br>Qui semel aspexit, quantum dimissa petitis<br>praestent, mature redeat repetatque relicta.<br>metiri se quemque suo modulo ac pede verum est.", "st": "1.7"}, {"sp": "SEC", "t": "VIII", "st": "1.8"}, {"sp": "N", "t": "Celso gaudere et bene rem gerere Albinovano<br>Musa rogata refer, comiti scribaeque Neronis,<br>si quaeret quid agam, dic multa et pulchra minantem<br>vivere nec recte nec suaviter; haud quia grando<br>contuderit vitis oleamque momorderit aestus,<br>nec quia longinquis armentum aegrotet in agris;<br>sed quia mente minus validus quam corpore toto<br>nil audire velim, nil discere, quod levet aegrum;<br>fidis offendar medicis, irascar amicis,<br>cur me funesto properent arcere veterno;<br>quae nocuere sequar, fugiam quae profore credam;<br>Romae Tibur amem ventosus, Tibure Romam.<br>Post haec, ut valeat, quo pacto rem gerat et se,<br>ut placeat iuveni percontare utque cohorti,<br>si dicet, “recte,” primum gaudere, subinde<br>praeceptum auriculis hoc instillare memento:<br>“ut tu fortunam, sic nos te, Celse, feremus.”", "st": "1.8"}, {"sp": "SEC", "t": "IX", "st": "1.9"}, {"sp": "N", "t": "Septimius, Claudi, nimirum intellegit unus,<br>quanti me facias, nam cum rogat et prece cogit<br>scilicet ut tibi se laudare et tradere coner,<br>dignum mente domoque legentis honesta Neronis,<br>munere cum fungi propioris censet amici,<br>quid possim videt ac novit me valdius ipso.<br>multa quidem dixi cur excusatus abirem;<br>sed timui mea ne finxisse minora putarer,<br>dissimilator opis propriae, mihi commodus uni.<br>sic ego, maioris fugiens opprobria culpae,<br>frontis ad urbanae descendi praemia, quod si<br>depositum laudas ob amici iussa pudorem,<br>scribe tui gregis hunc et fortem crede bonumque.", "st": "1.9"}, {"sp": "SEC", "t": "X", "st": "1.10"}, {"sp": "N", "t": "Urbis amatorem Fuscum salvere iubemus<br>ruris amatores, hac in re scilicet una<br>multum dissimiles, at cetera paene gemelli<br>fraternis animis (quidquid negat alter, et alter)<br>adnuimus pariter vetuli notique columbi.<br>Tu nidum servas; ego laudo ruris amoeni<br>rivos et musco circumlita saxa nemusque.<br>quid quaeris? vivo et regno, simul ista reliqui<br>quae vos ad caelum effertis rumore secundo,<br>utque sacerdotis fugitivus liba recuso;<br>pane egeo iam mellitis potiore placentis.<br>Vivere Naturae si convenienter oportet,<br>ponendaeque domo quaerenda est area primum,<br>novistine locum potiorem rure beato?<br>est ubi plus tepeant hiemes, ubi gratior aura<br>leniat et rabiem Canis et momenta Leonis,<br>cum semel accepit Solem furibundus acutum?<br>est ubi divellat somnos minus invida Cura?<br>deterius Libycis olet aut nitet herba lapillis?<br>purior in vicis aqua tendit rumpere plumbum,<br>quam quae per pronum trepidat cum murmure rivum?<br>nempe inter varias nutritur silva columnas,<br>laudaturque domus longos quae prospicit agros.<br>Naturam expelles furca, tamen usque recurret,<br>et mala perrumpet furtim fastidia victrix.", "st": "1.10"}, {"sp": "N", "t": "Non, qui Sidonio contendere callidus ostro<br>nescit Aquinatem potantia vellera fucum,<br>certius accipiet damnum propiusve medullis,<br>quam qui non poterit vero distinguere falsum,<br>quem res plus nimio delectavere secundae,<br>mutatae quatient. si quid mirabere, pones<br>invitus, fuge magna: licet sub paupere tecto<br>reges et regum vita praecurrere amicos.<br>Cervus equum pugna melior communibus herbis<br>pellebat, donec minor in certamine longo<br>imploravit opes hominis frenumque recepit;<br>sed postquam victor violens discessit ab hoste,<br>non equitem dorso, non frenum depulit ore.<br>sic qui pauperiem veritus potiore metallis<br>libertate caret, dominum vehet improbus atque<br>serviet aeternum, quia parvo nesciet uti.<br>cui non conveniet sua res, ut calceus olim,<br>si pede maior erit, subvertet, si minor, uret.<br>Laetus sorte tua vives sapienter, Aristi,<br>nec me dimittes incastigatum, ubi plura<br>cogere quam satis est ac non cessare videbor,<br>imperat aut servit collecta pecunia cuique,<br>tortum digna sequi potius quam ducere funem.<br>Haec tibi dictabam post fanum putre Vacunae,<br>excepto quod non simul esses, cetera laetus.", "st": "1.10"}, {"sp": "SEC", "t": "XI", "st": "1.11"}, {"sp": "N", "t": "Quid tibi visa Chios, Bullati, notaque Lesbos,<br>quid concinna Samos, quid Croesi regia Sardis,<br>Zmyrna quid et Colophon? maiora minorave fama,<br>cunctane prae Campo et Tiberino flumine sordent?<br>an venit in votum Attalicis ex urbibus una,<br>an Lebedum laudas odio maris atque viarum?<br>scis Lebedus quid sit: Gabiis desertior atque<br>Fidenis vicus; tamen illic vivere vellem,<br>oblitusque meorum, obliviscendus et illis,<br>Neptunum procul e terra spectare furentem.<br>Sed neque qui Capua Romam petit, imbre lutoque<br>aspersus, volet in caupona vivere; nec qui<br>frigus collegit, furnos et balnea laudat<br>ut fortunatam plene praestantia vitam;<br>nec si te validus iactaverit Auster in alto,<br>idcirco navem trans Aegaeum mare vendas.<br>Incolumi Rhodos et Mytilene pulchra facit quod<br>paenula solstitio, campestre nivalibus auris,<br>per brumam Tiberis, Sextili mense caminus.<br>dum licet ac voltum servat Fortuna benignum,<br>Romae laudetur Samos et Chios et Rhodos absens,<br>tu quamcumque deus tibi fortunaverit horam<br>grata sume manu, neu dulcia differ in annum;<br>ut quocumque loco fueris vixisse libenter<br>te dicas, nam si ratio et prudentia curas,<br>non locus effusi late maris arbiter aufert,<br>caelum, non animum, mutant, qui trans mare currunt,<br>strenua nos exercet inertia: navibus atque<br>quadrigis petimus bene vivere, quod petis hic est,<br>est Ulubris, animus si te non deficit aequus.", "st": "1.11"}, {"sp": "SEC", "t": "XII", "st": "1.12"}, {"sp": "N", "t": "Fructibus Agrippae Siculis, quos colligis, Icci,<br>si recte frueris, non est ut copia maior<br>ab Iove donari possit tibi. tolle querellas:<br>pauper enim non est, cui rerum suppetit usus,<br>si ventri bene, si lateri est pedibusque tuis, nil<br>divitiae poterunt regales addere maius.<br>si forte in medio positorum abstemius herbis<br>vivis et urtica, sic vives protinus, ut te<br>confestim liquidus Fortunae rivus inauret,<br>vel quia naturam mutare pecunia nescit,<br>vel quia cuncta putas una virtute minora.<br>Miramur, si Democriti pecus edit agellos<br>cultaque, dum peregre est animus sine corpore velox;<br>cum tu inter scabiem tantam et contagia lucri<br>nil parvum sapias et adhuc sublimia cures:<br>quae mare compescant causae, quid temperet annum,<br>stellae sponte sua iussaene vagentur et errent,<br>quid premat obscurum lunae, quid proferat orbem,<br>quid velit et possit rerum concordia discors,<br>Empedocles an Stertinium deliret acumen.<br>Verum seu piscis seu porrum et caepe trucidas,<br>utere Pompeio Grospho et, si quid petet, ultro<br>defer; nil Grosphus nisi verum orabit et aequum,<br>vilis amicorum est annona, bonis ubi quid deest.<br>Ne tamen ignores, quo sit Romana loco res,<br>Cantaber Agrippae, Claudi virtute Neronis<br>Armenius cecidit; ius imperiumque Phraates<br>Caesaris accepit genibus minor; aurea fruges<br>Italiae pleno defudit Copia cornu.", "st": "1.12"}, {"sp": "SEC", "t": "XIII", "st": "1.13"}, {"sp": "N", "t": "Ut proficiscentem docui te saepe diuque,<br>Augusto reddes signata volumina, Vini,<br>si validus, si laetus erit, si denique poscet;<br>ne studio nostri pecces odiumque libellis<br>sedulus importes opera vehemente minister.<br>si te forte meae gravis uret sarcina chartae,<br>abicito potius, quam quo perferre iuberis<br>clitellas ferus impingas, Asinaeque paternum<br>cognomen vertas in risum et fabula fias.<br>Viribus uteris per clivos, flumina, lamas.<br>victor propositi simul ac perveneris illuc,<br>sic positum servabis onus, ne forte sub ala<br>fasciculum portes librorum ut rusticus agnum,<br>ut vinosa glomus furtivae Pyrria lanae,<br>ut cum pilleolo soleas conviva tribulis.<br>neu volgo narres te sudavisse ferendo<br>carmina, quae possint oculos aurisque morari<br>Caesaris, oratus multa prece, nitere porro,<br>vade; vale; cave ne titubes mandataque frangas.", "st": "1.13"}, {"sp": "SEC", "t": "XIV", "st": "1.14"}, {"sp": "N", "t": "Vilice silvarum et mihi me reddentis agelli,<br>quem tu fastidis, habitatum quinque focis et<br>quinque bonos solitum Variam dimittere patres,<br>certemus, spinas animone ego fortius an tu<br>evellas agro, et melior sit Horatius an res.<br>Me quamvis Lamiae pietas et cura moratur,<br>fratrem maerentis, rapto de fratre dolentis<br>insolabiliter, tamen istuc mens animusque<br>fert et amat spatiis obstantia rumpere claustra,<br>rure ego viventem, tu dicis in urbe beatum.<br>cui placet alterius, sua nimirum est odio sors.<br>stultus uterque locum immeritum causatur inique:<br>in culpa est animus, qui se non effugit umquam.<br>Tu mediastinus tacita prece rura petebas,<br>nunc urbem et ludos et balnea vilicus optas:<br>me constare mihi scis et discedere tristem<br>quandocumque trahunt invisa negotia Romam,<br>non eadem miramur; eo disconvenit inter<br>meque et te. nam quae deserta et inhospita tesqua<br>credis, amoena vocat mecum qui sentit, et odit<br>quae tu pulchra putas, fornix tibi et uncta popina<br>incutiunt urbis desiderium, video, et quod<br>angulus iste feret piper et tus ocius uva,<br>nec vicina subest vinum praebere taberna<br>quae possit tibi, nec meretrix tibicina, cuius<br>ad strepitum salias terrae gravis; et tamen urges<br>iampridem non tacta ligonibus arva bovemque<br>disiunctum curas et strictis frondibus exples;<br>addit opus pigro rivus, si decidit imber,<br>multa mole docendus aprico parcere prato.", "st": "1.14"}, {"sp": "N", "t": "Nunc age, quid nostrum concentum dividat audi.<br>quem tenues decuere togae nitidique capilli,<br>quem scis immunem Cinarae placuisse rapaci,<br>quem bibulum liquidi media de luce Falerni,<br>cena brevis iuvat et prope rivum somnus in herba;<br>nec lusisse pudet, sed non incidere ludum,<br>non istic obliquo oculo mea commoda quisquam<br>limat, non odio obscuro morsuque venenat:<br>rident vicini glaebas et saxa moventem.<br>cum servis urbana diaria rodere mavis;<br>horum tu in numerum voto ruis: invidet usum<br>lignorum et pecoris tibi calo argutus et horti,<br>optat ephippia bos, piger optat arare caballus.<br>quam scit uterque libens censebo exerceat artem.", "st": "1.14"}, {"sp": "SEC", "t": "XV", "st": "1.15"}, {"sp": "N", "t": "Quae sit hiems Veliae, quod caelum, Vala, Salerni,<br>quorum hominum regio et qualis via (nam mihi Baias<br>Musa supervacuas Antonius, et tamen illis<br>me facit invisum, gelida cum perluor unda<br>per medium frigus, sane murteta relinqui<br>dictaque cessantem nervis elidere morbum<br>sulfura contemni vicus gemit, invidus aegris,<br>qui caput et stomachum supponere fontibus audent<br>Clusinis Gabiosque petunt et frigida rura.<br>mutandus locus est et deversoria nota<br>praeteragendus equus, “quo tendis? non mihi Cumas<br>est iter aut Baias,” laeva stomachosus habena<br>dicet eques; sed equi frenato est auris in ore);<br>maior utrum populum frumenti copia pascat;<br>collectosne bibant imbres puteosne perennis<br>iugis aquae (nam vina nihil moror illius orae:<br>rure meo possum quidvis perferre patique;<br>ad mare cum veni, generosum et lene requiro,<br>quod curas abigat, quod cum spe divite manet<br>in venas animumque meum, quod verba ministret,<br>quod me Lucanae iuvenem commendet amicae);<br>tractus uter pluris lepores, uter educet apros;<br>utra magis piscis et echinos aequora celent,<br>pinguis ut inde domum possim Phaeaxque reverti,<br>scribere te nobis, tibi nos accredere par est.", "st": "1.15"}, {"sp": "N", "t": "Maenius, ut rebus maternis atque paternis<br>fortiter absumptis urbanus coepit haberi<br>scurra vagus, non qui certum praesepe teneret,<br>impransus non qui civem dinosceret hoste,<br>quaelibet in quemvis opprobria fingere saevus,<br>pernicies et tempestas barathrumque macelli,<br>quidquid quaesierat, ventri donabat avaro.<br>hic ubi nequitiae fautoribus et timidis nil<br>aut paulum abstulerat, patinas cenabat omasi,<br>vilis et agninae, tribus ursis quod satis esset;<br>scilicet ut ventres lamna candente nepotum<br>diceret urendos correctus Bestius. idem,<br>quidquid erat nactus praedae maioris, ubi omne<br>verterat in fumum et cinerem, “non hercule miror,”<br>aiebat, “si qui comedunt bona, cum sit obeso<br>nil melius turdo, nil vulva pulchrius ampla.”<br>Nimirum hic ego sum. nam tuta et parvola laudo,<br>cum res deficiunt, satis inter vilia fortis:<br>verum ubi quid melius contingit et unctius, idem<br>vos sapere et solos aio bene vivere, quorum<br>conspicitur nitidis fundata pecunia villis.", "st": "1.15"}, {"sp": "SEC", "t": "XVI", "st": "1.16"}, {"sp": "N", "t": "Ne perconteris, fundus meus, optime Quincti,<br>arvo pascat erum an bacis opulentet olivae,<br>pomisne an pratis an amicta vitibus ulmo,<br>scribetur tibi forma loquaciter et situs agri.<br>Continui montes, ni dissocientur opaca<br>valle, sed ut veniens dextrum latus aspiciat sol,<br>laevum discedens curru fugiente vaporet.<br>temperiem laudes, quid si rubicunda benigni<br>corna vepres et pruna ferant? si quercus et ilex<br>multa fruge pecus, multa dominum iuvet umbra?<br>dicas adductum propius frondere Tarentum,<br>fons etiam rivo dare nomen idoneus, ut nec<br>frigidior Thracam nec purior ambiat Hebrus,<br>infirmo capiti fluit utilis, utilis alvo.<br>hae latebrae dulces, etiam, si credis, amoenae,<br>incolumem tibi me praestant Septembribus horis.<br>Tu recte vivis, si curas esse quod audis,<br>iactamus iam pridem omnis te Roma beatum;<br>sed vereor ne cui de te plus quam tibi credas,<br>neve putes alium sapiente bonoque beatum,<br>neu, si te populus sanum recteque valentem<br>dictitet, occultam febrem sub tempus edendi<br>dissimules, donec manibus tremor incidat unctis.<br>stultorum incurata pudor malus ulcera celat.", "st": "1.16"}, {"sp": "N", "t": "Si quis bella tibi terra pugnata marique<br>dicat et his verbis vacuas permulceat auris:<br>“tene magis salvum populus velit an populum tu,<br>servet in ambiguo, qui consulit et tibi et urbi,<br>Iuppiter,” Augusti laudes agnoscere possis:<br>cum pateris sapiens emendatusque vocari,<br>respondesne tuo, dic sodes, nomine? “nempe<br>vir bonus et prudens dici delector ego ac tu.”<br>qui dedit hoc hodie, cras, si volet, auferet, ut si<br>detulerit fasces indigno, detrahet idem.<br>“pone, meum est” inquit: pono tristisque recedo.<br>idem si clamet furem, neget esse pudicum,<br>contendat laqueo collum pressisse paternum,<br>mordear opprobriis falsis mutemque colores?<br>falsus honor iuvat et mendax infamia terret<br>quem nisi mendosum et medicandum? Vir bonus est quis?<br>“qui consulta patrum, qui leges iuraque servat,<br>quo multae magnaeque secantur iudice lites,<br>quo res sponsore et quo causae teste tenentur.”<br>sed videt hunc omnis domus et vicinia tota<br>introrsum turpem, speciosum pelle decora.<br>“nec furtum feci nec fugi,” si mihi dicat<br>servus, “habes pretium, loris non ureris,” aio.<br>“non hominem occidi:” “non pasces in cruce corvos.”<br>“sum bonus et frugi:” renuit negitatque Sabellus.", "st": "1.16"}, {"sp": "N", "t": "cautus enim metuit foveam lupus accipiterque<br>suspectos laqueos et opertum miluus hamum,<br>oderunt peccare boni virtutis amore,<br>tu nihil admittes in te formidine poenae:<br>sit spes fallendi, miscebis sacra profanis.<br>nam de mille fabae modiis cum surripis unum,<br>damnum est, non facinus, mihi pacto lenius isto.<br>vir bonus, omne forum quem spectat et omne tribunal,<br>quandocumque deos vel porco vel bove placat,<br>“Iane pater!” clare, clare cum dixit, “Apollo!”<br>labra movet metuens audiri: “pulchra Laverna,<br>da mihi fallere, da iusto sanctoque videri,<br>noctem peccatis et fraudibus obice nubem.”<br>Qui melior servo, qui liberior sit avarus,<br>in triviis fixum cum se demittit ob assem,<br>non video; nam qui cupiet, metuet quoque; porro,<br>qui metuens vivet, liber mihi non erit umquam,<br>perdidit arma, locum Virtutis deseruit, qui<br>semper in augenda festinat et obruitur re.<br>vendere cum possis captivum, occidere noli;<br>serviet utiliter; sine pascat durus aretque,<br>naviget ac mediis hiemet mercator in undis,<br>annonae prosit, portet frumenta penusque.<br>Vir bonus et sapiens audebit dicere: “Pentheu,<br>rector Thebarum, quid me perferre patique<br>indignum coges?” “Adimam bona.” “Nempe pecus, rem,<br>lectos, argentum: tollas licet.” “In manicis et<br>compedibus saevo te sub custode tenebo.”<br>“Ipse deus, simul atque volam, me solvet.” opinor,<br>hoc sentit “moriar.” mors ultima linea rerum est.", "st": "1.16"}, {"sp": "SEC", "t": "XVII", "st": "1.17"}, {"sp": "N", "t": "Quamvis, Scaeva, satis per te tibi consulis et scis,<br>quo tandem pacto deceat maioribus uti,<br>disce, docendus adhuc quae censet amiculus, ut si<br>caecus iter monstrare velit; tamen aspice si quid<br>et nos, quod cures proprium fecisse, loquamur.<br>Si te grata quies et primam somnus in horam<br>delectat, si te pulvis strepitusque rotarum,<br>si laedit caupona, Ferentinum ire iubebo,<br>nam neque divitibus contingunt gaudia solis,<br>nec vixit male, qui natus moriensque fefellit.<br>si prodesse tuis pauloque benignius ipsum<br>te tractare voles, accedes siccus ad unctum.<br>“Si pranderet holus patienter, regibus uti<br>nollet Aristippus.” “si sciret regibus uti,<br>fastidiret holus qui me notat.” utrius horum<br>verba probes et facta doce, vel iunior audi<br>cur sit Aristippi potior sententia, namque<br>mordacem Cynicum sic eludebat, ut aiunt:<br>“scurror ego ipse mihi, populo tu; rectius hoc et<br>splendidius multo est. equus ut me portet, alat rex,<br>officium facio; tu poscis vilia, verum<br>dante minor, quamvis fers te nullius egentem.”<br>omnis Aristippum decuit color et status et res,<br>temptantem maiora, fere praesentibus aequum,<br>contra, quem duplici panno patientia velat,<br>mirabor, vitae via si conversa decebit.<br>alter purpureum non exspectabit amictum,<br>quidlibet indutus celeberrima per loca vadet,<br>personamque feret non inconcinnus utramque;<br>alter Mileti textam cane peius et angui<br>vitabit chlamydem, morietur frigore, si non<br>rettuleris pannum. refer et sine vivat ineptus.", "st": "1.17"}, {"sp": "N", "t": "Res gerere et captos ostendere civibus hostis<br>attingit solium Iovis et caelestia temptat:<br>principibus placuisse viris non ultima laus est.<br>non cuivis homini contingit adire Corinthum.<br>sedit qui timuit ne non succederet. “Esto.<br>quid, qui pervenit, fecitne viriliter?” atqui<br>hic est aut nusquam, quod quaerimus, hic onus horret,<br>ut parvis animis et parvo corpore maius;<br>hic subit et perfert, aut virtus nomen inane est,<br>aut decus et pretium recte petit experiens vir.<br>Coram rege sua de paupertate tacentes<br>plus poscente ferent: distat, sumasne pudenter<br>an rapias; atqui rerum caput hoc erat, hic fons.<br>“indotata mihi soror est, paupercula mater,<br>et fundus nec vendibilis nec pascere firmus,”<br>qui dicit, clamat, “victum date!” succinit alter,<br>“et mihi!” dividuo findetur munere quadra,<br>sed tacitus pasci si posset corvus, haberet<br>plus dapis et rixae multo minus invidiaeque.<br>Brundisium comes aut Surrentum ductus amoenum<br>qui queritur salebras et acerbum frigus et imbres,<br>aut cistam effractam et subducta viatica plorat,<br>nota refert meretricis acumina, saepe catellam,<br>saepe periscelidem raptam sibi flentis, uti mox<br>nulla fides damnis verisque doloribus adsit,<br>nec semel irrisus triviis attollere curat<br>fracto crure planum, licet illi plurima manet<br>lacrima, per sanctum iuratus dicat Osirim:<br>“credite, non ludo; crudeles, tollite claudum!”<br>“quaere peregrinum,” vicinia rauca reclamat.", "st": "1.17"}, {"sp": "SEC", "t": "XVIII", "st": "1.18"}, {"sp": "N", "t": "Si bene te novi, metues, liberrime Lolli,<br>scurrantis speciem praebere, professus amicum<br>ut matrona meretrici dispar erit atque<br>discolor, infido scurrae distabit amicus,<br>est huic diversum vitio vitium prope maius,<br>asperitas agrestis et inconcinna gravisque,<br>quae se commendat tonsa cute, dentibus atris,<br>dum volt libertas dici mera veraque virtus,<br>virtus est medium vitiorum et utrimque reductum.<br>alter in obsequium plus aequo pronus et imi<br>derisor lecti sic nutum divitis horret,<br>sic iterat voces et verba cadentia tollit,<br>ut puerum saevo credas dictata magistro<br>reddere vel partis mimum tractare secundas.<br>alter rixatur de lana saepe caprina,<br>propugnat nugis armatus: “scilicet, ut non<br>sit mihi prima fides, et vere quod placet ut non<br>acriter elatrem! pretium aetas altera sordet.”<br>ambigitur quid enim? Castor sciat an Dolichos plus;<br>Brundisium Minuci melius via ducat an Appi.", "st": "1.18"}, {"sp": "N", "t": "Quem damnosa Venus, quem praeceps alea nudat,<br>gloria quem supra vires et vestit et unguit,<br>quem tenet argenti sitis importuna famesque,<br>quem paupertatis pudor et fuga, dives amicus,<br>saepe decem vitiis instructior, odit et horret,<br>aut, si non odit, regit ac veluti pia mater<br>plus quam se sapere et virtutibus esse priorem<br>volt et ait prope vera: “meae (contendere noli)<br>stultitiam patiuntur opes; tibi parvola res est.<br>arta decet sanum comitem toga; desine mecum<br>certare.” Eutrapelus, cuicumque nocere volebat,<br>vestimenta dabat pretiosa: “beatus enim iam<br>cum pulchris tunicis sumet nova consilia et spes,<br>dormiet in lucem, scorto postponet honestum<br>officium, nummos alienos pascet, ad imum<br>Thraex erit aut holitoris aget mercede caballum.”<br>Arcanum neque tu scrutaberis illius umquam,<br>commissumque teges et vino tortus et ira.<br>nec tua laudabis studia aut aliena reprendes,<br>nec, cum venari volet ille, poemata panges.", "st": "1.18"}, {"sp": "N", "t": "gratia sic fratrum geminorum, Amphionis atque<br>Zethi, dissiluit, donec suspecta severo<br>conticuit lyra. fraternis cessisse putatur<br>moribus Amphion: tu cede potentis amici<br>lenibus imperiis, quotiensque educet in agros<br>Aetolis onerata plagis iumenta canesque,<br>surge et inhumanae senium depone Camenae,<br>cenes ut pariter pulmenta laboribus empta:<br>Romanis sollemne viris opus, utile famae<br>vitaeque et membris; praesertim cum valeas et<br>vel cursu superare canem vel viribus aprum<br>possis, adde virilia quod speciosius arma<br>non est qui tractet; scis, quo clamore coronae<br>proelia sustineas campestria; denique saevam<br>militiam puer et Cantabrica bella tulisti<br>sub duce qui templis Parthorum signa refigit<br>nunc et, si quid abest, Italis adiudicat armis.<br>Ac ne te retrahas et inexcusabilis absis,<br>quamvis nil extra numerum fecisse modumque<br>curas, interdum nugaris rure paterno:<br>partitur lintres exercitus, Actia pugna<br>te duce per pueros hostili more refertur;<br>adversarius est frater, lacus Hadria, donec<br>alterutrum velox Victoria fronde coronet,<br>consentire suis studiis qui crediderit te,<br>fautor utroque tuum laudabit pollice ludum.", "st": "1.18"}, {"sp": "N", "t": "Protinus ut moneam (si quid monitoris eges tu)<br>quid de quoque viro et cui dicas, saepe videto,<br>percontatorem fugito: nam garrulus idem est,<br>nec retinent patulae commissa fideliter aures,<br>et semel emissum volat irrevocabile verbum,<br>non ancilla tuum iecur ulceret ulla puerve<br>intra marmoreum venerandi limen amici,<br>ne dominus pueri pulchri caraeve puellae<br>munere te parvo beet aut incommodus angat.<br>qualem commendes, etiam atque etiam aspice, ne mox<br>incutiant aliena tibi peccata pudorem,<br>fallimur et quondam non dignum tradimus: ergo<br>quem sua culpa premet, deceptus omitte tueri,<br>ut penitus notum, si temptent crimina, serves<br>tuterisque tuo fidentem praesidio: qui<br>dente Theonino cum circumroditur, ecquid<br>ad te post paulo ventura pericula sentis?<br>nam tua res agitur, paries cum proximus ardet,<br>et neglecta solent incendia sumere vires.<br>Dulcis inexpertis cultura potentis amici:<br>expertus metuit. tu, dum tua navis in alto est,<br>hoc age, ne mutata retrorsum te ferat aura.<br>oderunt hilarem tristes tristemque iocosi,<br>sedatum celeres, agilem navumque remissi;<br>potores [bibuli media de nocte Falerni]<br>[oderunt] porrecta negantem pocula, quamvis<br>nocturnos iures te formidare tepores.<br>deme supercilio nubem: plerumque modestus<br>occupat obscuri speciem, taciturnus acerbi.", "st": "1.18"}, {"sp": "N", "t": "Inter cuncta leges et percontabere doctos,<br>qua ratione queas traducere leniter aevum,<br>num te semper inops agitet vexetque cupido,<br>num pavor et rerum mediocriter utilium spes,<br>virtutem doctrina paret Naturane donet,<br>quid minuat curas, quid te tibi reddat amicum,<br>quid pure tranquillet, honos an dulce lucellum,<br>an secretum iter et fallentis semita vitae.<br>Me quotiens reficit gelidus Digentia rivus,<br>quem Mandela bibit, rugosus frigore pagus,<br>quid sentire putas? quid credis, amice, precari?<br>sit mihi quod nunc est, etiam minus, et mihi vivam<br>quod superest aevi, si quid superesse volunt di;<br>sit bona librorum et provisae frugis in annum<br>copia, neu fluitem dubiae spe pendulus horae.<br>Sed satis est orare Iovem, qui ponit et aufert,<br>det vitam, det opes; aequum mi animum ipse parabo.", "st": "1.18"}, {"sp": "SEC", "t": "XIX", "st": "1.19"}, {"sp": "N", "t": "Prisco si credis, Maecenas docte, Cratino,<br>nulla placere diu nec vivere carmina possunt,<br>quae scribuntur aquae potoribus. ut male sanos<br>adscripsit Liber Satyris Faunisque poetas,<br>vina fere dulces oluerunt mane Camenae.<br>laudibus arguitur vini vinosus Homerus;<br>Ennius ipse pater numquam nisi potus ad arma<br>prosiluit dicenda. “Forum Putealque Libonis<br>mandabo siccis, adimam cantare severis:”<br>hoc simul edixi, non cessavere poetae<br>nocturno certare mero, putere diurno,<br>quid? si quis voltu torvo ferus et pede nudo<br>exiguaeque togae simulet textore Catonem,<br>virtutemne repraesentet moresque Catonis?<br>rupit Iarbitam Timagenis aemula lingua,<br>dum studet urbanus tenditque disertus haberi.<br>decipit exemplar vitiis imitabile: quod si<br>pallerem casu, biberent exsangue cuminum.<br>o imitatores, servum pecus, ut mihi saepe<br>bilem, saepe iocum vestri movere tumultus!", "st": "1.19"}, {"sp": "N", "t": "Libera per vacuum posui vestigia princeps,<br>non aliena meo pressi pede. qui sibi fidet,<br>dux reget examen. Parios ego primus iambos<br>ostendi Latio, numeros animosque secutus<br>Archilochi, non res et agentia verba Lycamben.<br>ac ne me foliis ideo brevioribus ornes,<br>quod timui mutare modos et carminis artem,<br>temperat Archilochi Musam pede mascula Sappho,<br>temperat Alcaeus, sed rebus et ordine dispar,<br>nec socerum quaerit, quem versibus oblinat atris,<br>nec sponsae laqueum famoso carmine nectit,<br>hunc ego, non alio dictum prius ore, Latinus<br>volgavi fidicen. iuvat immemorata ferentem<br>ingenuis oculisque legi manibusque teneri.<br>Scire velis, mea cur ingratus opuscula lector<br>laudet ametque domi, premat extra limen iniquus:<br>non ego ventosae plebis suffragia venor<br>impensis cenarum et tritae munere vestis;<br>non ego, nobilium scriptorum auditor et ultor,<br>grammaticas ambire tribus et pulpita dignor.<br>hinc illae lacrimae. “spissis indigna theatris<br>scripta pudet recitare et nugis addere pondus,”<br>si dixi, “rides,” ait, “et Iovis auribus ista<br>servas: fidis enim manare poetica mella<br>te solum, tibi pulcher.” ad haec ego naribus uti<br>formido et, luctantis acuto ne secer ungui,<br>“displicet iste locus,” clamo et diludia posco,<br>ludus enim genuit trepidum certamen et iram,<br>ira truces inimicitias et funebre bellum.", "st": "1.19"}, {"sp": "SEC", "t": "XX", "st": "1.20"}, {"sp": "N", "t": "Vertumnum Ianumque, liber, spectare videris,<br>scilicet ut prostes Sosiorum pumice mundus.<br>odisti clavis et grata sigilla pudico;<br>paucis ostendi gemis et communia laudas,<br>non ita nutritus, fuge quo descendere gestis.<br>non erit emisso reditus tibi. “quid miser egi?<br>quid volui?” dices, ubi quis te laeserit, et scis<br>in breve te cogi, cum plenus languet amator.<br>Quod si non odio peccantis desipit augur,<br>carus eris Romae, donec te deserat aetas;<br>contrectatus ubi manibus sordescere volgi<br>coeperis, aut tineas pasces taciturnus inertis<br>aut fugies Uticam aut vinctus mitteris Ilerdam.<br>ridebit monitor non exauditus, ut ille<br>qui male parentem in rupes protrusit asellum<br>iratus: quis enim invitum servare laboret?<br>hoc quoque te manet, ut pueros elementa docentem<br>occupet extremis in vicis balba senectus.<br>Cum tibi sol tepidus pluris admoverit auris,<br>me libertino natum patre et in tenui re<br>maiores pinnas nido extendisse loqueris,<br>ut quantum generi demas virtutibus addas;<br>me primis urbis belli placuisse domique,<br>corporis exigui, praecanum, solibus aptum,<br>irasci celerem, tamen ut placabilis essem.<br>forte meum si quis te percontabitur aevum,<br>me quater undenos sciat implevisse Decembris,<br>collegam Lepidum quo duxit Lollius anno.", "st": "1.20"}, {"sp": "HDR", "t": "Liber II", "st": "2"}, {"sp": "SEC", "t": "I", "st": "2.1"}, {"sp": "N", "t": "Cum tot sustineas et tanta negotia solus,<br>res Italas armis tuteris, moribus ornes,<br>legibus emendes, in publica commoda peccem,<br>si longo sermone morer tua tempora, Caesar.<br>Romulus et Liber pater et cum Castore Pollux,<br>post ingentia facta deorum in templa recepti,<br>dum terras hominumque colunt genus, aspera bella<br>componunt, agros assignant, oppida condunt,<br>ploravere suis non respondere favorem<br>speratum meritis, diram qui contudit hydram<br>notaque fatali portenta labore subegit,<br>comperit invidiam supremo fine domari,<br>urit enim fulgore suo, qui praegravat artis<br>infra se positas; exstinctus amabitur idem.<br>praesenti tibi maturos largimur honores,<br>iurandasque tuum per numen ponimus aras,<br>nil oriturum alias, nil ortum tale fatentes.<br>Sed tuus hic populus sapiens et iustus in uno,<br>te nostris ducibus, te Grais anteferendo,<br>cetera nequaquam simili ratione modoque<br>aestimat et, nisi quae terris semota suisque<br>temporibus defuncta videt, fastidit et odit;<br>sic fautor veterum, ut tabulas peccare vetantis,<br>quas bis quinque viri sanxerunt, foedera regum<br>vel Gabiis vel cum rigidis aequata Sabinis,<br>pontificum libros, annosa volumina vatum<br>dictitet Albano Musas in monte locutas.", "st": "2.1"}, {"sp": "N", "t": "Si, quia Graiorum sunt antiquissima quaeque<br>scripta vel optima, Romani pensantur eadem<br>scriptores trutina, non est quod multa loquamur:<br>nil intra est olea, nil extra est in nuce duri;<br>venimus ad summum fortunae, pingimus atque<br>psallimus et luctamur Achivis doctius unctis.<br>Si meliora dies, ut vina, poemata reddit,<br>scire velim, chartis pretium quotus arroget annus.<br>scriptor abhinc annos centum qui decidit, inter<br>perfectos veteresque referri debet an inter<br>vilis atque novos? excludat iurgia finis.<br>“est vetus atque probus, centum qui perficit annos.”<br>quid, qui deperiit minor uno mense vel anno,<br>inter quos referendus erit? veteresne poetas,<br>an quos et praesens et postera respuat aetas?<br>“iste quidem veteres inter ponetur honeste,<br>qui vel mense brevi vel toto est iunior anno.”<br>utor permisso, caudaeque pilos ut equinae<br>paulatim vello et demo unum, demo etiam unum,<br>dum cadat elusus ratione ruentis acervi,<br>qui redit in fastos et virtutem aestimat annis<br>miraturque nihil nisi quod Libitina sacravit.<br>Ennius et sapiens et fortis et alter Homerus,<br>ut critici dicunt, leviter curare videtur,<br>quo promissa cadant et somnia Pythagorea.", "st": "2.1"}, {"sp": "N", "t": "Naevius in manibus non est et mentibus haeret<br>paene recens? adeo sanctum est vetus omne poema,<br>ambigitur quotiens, uter utro sit prior, aufert<br>Pacuvius docti famam senis, Accius alti,<br>dicitur Afrani toga convenisse Menandro,<br>Plautus ad exemplar Siculi properare Epicharmi,<br>vincere Caecilius gravitate, Terentius arte.<br>hos ediscit et hos arto stipata theatro<br>spectat Roma potens; habet hos numeratque poetas<br>ad nostrum tempus Livi scriptoris ab aevo.<br>Interdum volgus rectum videt, est ubi peccat,<br>si veteres ita miratur laudatque poetas,<br>ut nihil anteferat, nihil illis comparet, errat.<br>si quaedam nimis antique, si pleraque dure<br>dicere credit eos, ignave multa fatetur,<br>et sapit et mecum facit et Iove iudicat aequo,<br>non equidem insector delendave carmina Livi<br>esse reor, memini quae plagosum mihi parvo<br>Orbilium dictare; sed emendata videri<br>pulchraque et exactis minimum distantia miror,<br>inter quae verbum emicuit si forte decorum, et<br>si versus paulo concinnior unus et alter,<br>iniuste totum ducit venditque poema.", "st": "2.1"}, {"sp": "N", "t": "Indignor quicquam reprehendi, non quia crasse<br>compositum illepideve putetur, sed quia nuper,<br>nec veniam antiquis, sed honorem et praemia posci,<br>recte necne crocum floresque perambulet Attae<br>fabula si dubitem, clament periisse pudorem<br>cuncti paene patres, ea cum reprehendere coner,<br>quae gravis Aesopus, quae doctus Roscius egit;<br>vel quia nil rectum, nisi quod placuit sibi, ducunt,<br>vel quia turpe putant parere minoribus, et quae<br>imberbes didicere senes perdenda fateri.<br>iam Saliare Numae carmen qui laudat et illud,<br>quod mecum ignorat, solus volt scire videri,<br>ingeniis non ille favet plauditque sepultis,<br>nostra sed impugnat, nos nostraque lividus odit.<br>Quod si tam Graecis novitas invisa fuisset<br>quam nobis, quid nunc esset vetus? aut quid haberet<br>quod legeret tereretque viritim publicus usus?<br>Ut primum positis nugari Graecia bellis<br>coepit et in vitium fortuna labier aequa,<br>nunc athletarum studiis, nunc arsit equorum,<br>marmoris aut eboris fabros aut aeris amavit,<br>suspendit picta voltum mentemque tabella,<br>nunc tibicinibus, nunc est gavisa tragoedis;<br>sub nutrice puella velut si luderet infans,<br>quod cupide petiit, mature plena reliquit.<br>quid placet aut odio est, quod non mutabile credas?<br>hoc paces habuere bonae ventique secundi.", "st": "2.1"}, {"sp": "N", "t": "Romae dulce diu fuit et sollemne reclusa<br>mane domo vigilare, clienti promere iura,<br>cautos nominibus rectis expendere nummos,<br>maiores audire, minori dicere, per quae<br>crescere res posset, minui damnosa libido.<br>mutavit mentem populus levis et calet uno<br>scribendi studio; pueri patresque severi<br>fronde comas vincti cenant et carmina dictant.<br>ipse ego, qui nullos me adfirmo scribere versus,<br>invenior Parthis mendacior, et prius orto<br>sole vigil calamum et chartas et scrinia posco,<br>navem agere ignarus navis timet; habrotonum aegro<br>non audet nisi qui didicit dare; quod medicorum est<br>promittunt medici; tractant fabrilia fabri:<br>scribimus indocti doctique poemata passim.<br>Hic error tamen et levis haec insania quantas<br>virtutes habeat, sic collige, vatis avarus<br>non temere est animus; versus amat, hoc studet unum;<br>detrimenta, fugas servorum, incendia ridet;<br>non fraudem socio puerove incogitat ullam<br>pupillo; vivit siliquis et pane secundo;<br>militiae quamquam piger et malus, utilis urbi,<br>si das hoc, parvis quoque rebus magna iuvari.", "st": "2.1"}, {"sp": "N", "t": "os tenerum pueri balbumque poeta figurat,<br>torquet ab obscenis iam nunc sermonibus aurem,<br>mox etiam pectus praeceptis format amicis,<br>asperitatis et invidiae corrector et irae,<br>recte facta refert, orientia tempora notis<br>instruit exemplis, inopem solatur et aegrum,<br>castis cum pueris ignara puella mariti<br>disceret unde preces, vatem ni Musa dedisset?<br>poscit opem chorus et praesentia numina sentit,<br>caelestis implorat aquas docta prece blandus,<br>avertit morbos, metuenda pericula pellit,<br>impetrat et pacem et locupletem frugibus annum,<br>carmine di superi placantur, carmine Manes.<br>Agricolae prisci, fortes parvoque beati,<br>condita post frumenta levantes tempore festo<br>corpus et ipsum animum spe finis dura ferentem,<br>cum sociis operum et pueris et coniuge fida,<br>Tellurem porco, Silvanum lacte piabant,<br>floribus et vino Genium memorem brevis aevi,<br>Fescennina per hunc inventa licentia morem<br>versibus alternis opprobria rustica fudit,<br>libertasque recurrentis accepta per annos<br>lusit amabiliter, donec iam saevus apertam<br>in rabiem coepit verti iocus et per honestas<br>ire domos impune minax, doluere cruento<br>dente lacessiti; fuit intactis quoque cura<br>condicione super communi; quin etiam lex<br>poenaque lata, malo quae nollet carmine quemquam<br>describi: vertere modum, formidine fustis<br>ad bene dicendum delectandumque redacti.", "st": "2.1"}, {"sp": "N", "t": "Graecia capta ferum victorem cepit et artis<br>intulit agresti Latio, sic horridus ille<br>defluxit numerus Saturnius, et grave virus<br>munditiae pepulere; sed in longum tamen aevum<br>manserunt hodieque manent vestigia ruris.<br>serus enim Graecis admovit acumina chartis<br>et post Punica bella quietus quaerere coepit,<br>quid Sophocles et Thespis et Aeschylus utile ferrent.<br>temptavit quoque rem, si digne vertere posset,<br>et placuit sibi, natura sublimis et acer:<br>nam spirat tragicum satis et feliciter audet,<br>sed turpem putat inscite metuitque lituram.<br>Creditur, ex medio quia res accersit, habere<br>sudoris minimum, sed habet Comoedia tanto<br>plus oneris, quanto veniae minus, adspice, Plautus<br>quo pacto partis tutetur amantis ephebi,<br>ut patris attenti, lenonis ut insidiosi,<br>quantus sit Dossennus edacibus in parasitis,<br>quam non adstricto percurrat pulpita socco.<br>gestit enim nummum in loculos demittere, post hoc<br>securus cadat an recto stet fabula talo.<br>Quem tulit ad scaenam ventoso Gloria curru,<br>exanimat lentus spectator, sedulus inflat:<br>sic leve, sic parvum est, animum quod laudis avarum<br>subruit aut reficit. valeat res ludicra, si me<br>palma negata macrum, donata reducit opimum.", "st": "2.1"}, {"sp": "N", "t": "Saepe etiam audacem fugat hoc terretque poetam,<br>quod numero plures, virtute et honore minores,<br>indocti stolidique et depugnare parati,<br>si discordet eques, media inter carmina poscunt<br>aut ursum aut pugiles: his nam plebecula gaudet.<br>verum equitis quoque iam migravit ab aure voluptas<br>omnis ad incertos oculos et gaudia vana.<br>quattuor aut pluris aulaea premuntur in horas,<br>dum fugiunt equitum turmae peditumque catervae;<br>mox trahitur manibus regum fortuna retortis,<br>esseda festinant, pilenta, petorrita, naves,<br>captivum portatur ebur, captiva Corinthus.<br>si foret in terris, rideret Democritus, seu<br>diversum confusa genus panthera camelo<br>sive elephans albus volgi converteret ora;<br>spectaret populum ludis attentius ipsis<br>ut sibi praebentem nimio spectacula plura:<br>scriptores autem narrare putaret asello<br>fabellam surdo. nam quae pervincere voces<br>evaluere sonum, referunt quem nostra theatra?", "st": "2.1"}, {"sp": "N", "t": "Garganum mugire putes nemus aut mare Tuscum;<br>tanto cum strepitu ludi spectantur et artes<br>divitiaeque peregrinae, quibus oblitus actor<br>cum stetit in scaena, concurrit dextera laevae.<br>“dixit adhuc aliquid?” “nil sane.” “quid placet ergo?”<br>“lana Tarentino violas imitata veneno.”<br>ac ne forte putes me, quae facere ipse recusem,<br>cum recte tractent alii, laudare maligne,<br>ille per extentum funem mihi posse videtur<br>ire poeta, meum qui pectus inaniter angit,<br>irritat, mulcet, falsis terroribus implet,<br>ut magus, et modo me Thebis, modo ponit Athenis.<br>Verum age et his, qui se lectori credere malunt<br>quam spectatoris fastidia ferre superbi,<br>curam redde brevem, si munus Apolline dignum<br>vis complere libris et vatibus addere calcar,<br>ut studio maiore petant Helicona virentem.<br>Multa quidem nobis facimus mala saepe poetae<br>(ut vineta egomet caedam mea), cum tibi librum<br>sollicito damus aut fesso; cum laedimur, unum<br>si quis amicorum est ausus reprehendere versum;<br>cum loca iam recitata revolvimus irrevocati;<br>cum lamentamur non apparere labores<br>nostros et tenui deducta poemata filo;<br>cum speramus eo rem venturam ut, simul atque<br>carmina rescieris nos fingere, commodus ultro<br>arcessas et egere vetes et scribere cogas.", "st": "2.1"}, {"sp": "N", "t": "sed tamen est operae pretium cognoscere, qualis<br>aedituos habeat belli spectata domique<br>Virtus, indigno non committenda poetae.<br>gratus Alexandro regi magno fuit ille<br>Choerilus, incultis qui versibus et male natis<br>rettulit acceptos, regale nomisma, Philippos;<br>sed veluti tractata notam labemque remittunt<br>atramenta, fere scriptores carmine foedo<br>splendida facta linunt, idem rex ille, poema<br>qui tam ridiculum tam care prodigus emit,<br>edicto vetuit, ne quis se praeter Apellen<br>pingeret, aut alius Lysippo duceret aera<br>fortis Alexandri voltum simulantia. quod si<br>iudicium subtile videndis artibus illud<br>ad libros et ad haec Musarum dona vocares,<br>Boeotum in crasso iurares aere natum.<br>At neque dedecorant tua de se iudicia atque<br>munera, quae multa dantis cum laude tulerunt<br>dilecti tibi Vergilius Variusque poetae,<br>nec magis expressi voltus per aenea signa,<br>quam per vatis opus mores animique virorum<br>clarorum apparent, nec sermones ego mallem<br>repentis per humum quam res componere gestas,<br>terrarumque situs et flumina dicere, et arces<br>montibus impositas et barbara regna, tuisque<br>auspiciis totum confecta duella per orbem,<br>claustraque custodem pacis cohibentia Ianum,<br>et formidatam Parthis te principe Romam,<br>si quantum cuperem possem quoque; sed neque parvum<br>carmen maiestas recipit tua, nec meus audet<br>rem temptare pudor quam vires ferre recusent.", "st": "2.1"}, {"sp": "N", "t": "sedulitas autem stulte quem diligit urget,<br>praecipue cum se numeris commendat et arte;<br>discit enim citius meminitque libentius illud<br>quod quis deridet, quam quod probat et veneratur.<br>nil moror officium quod me gravat, ac neque ficto<br>in peius voltu proponi cereus usquam<br>nec prave factis decorari versibus opto,<br>ne rubeam pingui donatus munere, et una<br>cum scriptore meo, capsa porrectus operta,<br>deferar in vicum vendentem tus et odores<br>et piper et quidquid chartis amicitur ineptis.", "st": "2.1"}, {"sp": "SEC", "t": "II", "st": "2.2"}, {"sp": "N", "t": "Flore, bono claraque fidelis amice Neroni,<br>si quis forte velit puerum tibi vendere natum<br>Tibure vel Gabiis, et tecum sic agat: “hic et<br>candidus et talos a vertice pulcher ad imos<br>fiet eritque tuus nummorum milibus octo,<br>verna ministeriis ad nutus aptus erilis,<br>litterulis Graecis imbutus, idoneus arti<br>cuilibet; argilla quidvis imitaberis uda;<br>quin etiam canet indoctum sed dulce bibenti.<br>multa fidem promissa levant, ubi plenius aequo<br>laudat venalis qui volt extrudere merces,<br>res urget me nulla; meo sum pauper in aere.<br>nemo hoc mangonum faceret tibi; non temere a me<br>quivis ferret idem. semel hic cessavit et, ut fit,<br>in scalis latuit metuens pendentis habenae:<br>des nummos, excepta nihil te si fuga laedit:”<br>ille ferat pretium poenae securus, opinor,<br>prudens emisti vitiosum; dicta tibi est lex:<br>insequeris tamen hunc et lite moraris iniqua?<br>dixi me pigrum proficiscenti tibi, dixi<br>talibus officiis prope mancum, ne mea saevus<br>iurgares ad te quod epistula nulla rediret.<br>quid tum profeci, mecum facientia iura<br>si tamen attemptas? quereris super hoc etiam, quod<br>exspectata tibi non mittam carmina mendax.", "st": "2.2"}, {"sp": "N", "t": "Luculli miles collecta viatica multis<br>aerumnis, lassus dum noctu stertit, ad assem<br>perdiderat: post hoc vehemens lupus, et sibi et hosti<br>iratus pariter, ieiunis dentibus acer,<br>praesidium regale loco deiecit, ut aiunt,<br>summe munito et multarum divite rerum,<br>clarus ob id factum donis ornatur honestis,<br>accipit et bis dena super sestertia nummum,<br>forte sub hoc tempus castellum evertere praetor<br>nescio quod cupiens hortari coepit eundem<br>verbis quae timido quoque possent addere mentem:<br>“i, bone, quo virtus tua te vocat, i pede fausto,<br>grandia laturus meritorum praemia, quid stas?”<br>post haec ille catus, quantumvis rusticus: “ibit,<br>ibit eo, quo vis, qui zonam perdidit,” inquit.<br>Romae nutriri mihi contigit atque doceri<br>iratus Grais quantum nocuisset Achilles.<br>adiecere bonae paulo plus artis Athenae,<br>scilicet ut vellem curvo dinoscere rectum<br>atque inter silvas Academi quaerere verum.<br>dura sed emovere loco me tempora grato<br>civilisque rudem belli tulit aestus in arma<br>Caesaris Augusti non responsura lacertis.<br>unde simul primum me dimisere Philippi,<br>decisis humilem pennis inopemque paterni<br>et laris et fundi, paupertas impulit audax<br>ut versus facerem: sed quod non desit habentem<br>quae poterunt umquam satis expurgare cicutae,<br>ni melius dormire putem quam scribere versus?", "st": "2.2"}, {"sp": "N", "t": "Singula de nobis anni praedantur euntes;<br>eripuere iocos, Venerem, convivia, ludum;<br>tendunt extorquere poemata: quid faciam vis?<br>denique non omnes eadem mirantur amantque:<br>carmine tu gaudes, hic delectatur iambis,<br>ille Bioneis sermonibus et sale nigro.<br>tres mihi convivae prope dissentire videntur,<br>poscentes vario multum diversa palato,<br>quid dem? quid non dem? renuis tu, quod iubet alter;<br>quod petis, id sane est invisum acidumque duobus.<br>Praeter cetera me Romaene poemata censes<br>scribere posse inter tot curas totque labores?<br>hic sponsum vocat, hic auditum scripta, relictis<br>omnibus officiis; cubat hic in colle Quirini,<br>hic extremo in Aventino, visendus uterque;<br>intervalla vides humane commoda. “verum<br>purae sunt plateae, nihil ut meditantibus obstet.”<br>festinat calidus mulis gerulisque redemptor,<br>torquet nunc lapidem, nunc ingens machina tignum,<br>tristia robustis luctantur funera plaustris,<br>hac rabiosa fugit canis, hac lutulenta ruit sus:<br>i nunc et versus tecum meditare canoros.<br>scriptorum chorus omnis amat nemus et fugit urbem,<br>rite cliens Bacchi somno gaudentis et umbra:<br>tu me inter strepitus nocturnos atque diurnos<br>vis canere et contracta sequi vestigia vatum?<br>ingenium, sibi quod vacuas desumpsit Athenas<br>et studiis annos septem dedit insenuitque<br>libris et curis, statua taciturnius exit<br>plerumque et risu populum quatit: hic ego rerum<br>fluctibus in mediis et tempestatibus urbis<br>verba lyrae motura sonum conectere digner?", "st": "2.2"}, {"sp": "N", "t": "Frater erat Romae consulti rhetor, ut alter<br>alterius sermone meros audiret honores,<br>Gracchus ut hic illi, foret huic ut Mucius ille.<br>qui minus argutos vexat furor iste poetas?<br>carmina compono, hic elegos. mirabile visu<br>caelatumque novem Musis opus! adspice primum,<br>quanto cum fastu, quanto molimine circum-<br>spectemus vacuam Romanis vatibus aedem!<br>mox etiam, si forte vacas, sequere et procul audi,<br>quid ferat et qua re sibi nectat uterque coronam.<br>caedimur et totidem plagis consumimus hostem<br>lento Samnites ad lumina prima duello.<br>discedo Alcaeus puncto illius; ille meo quis?<br>quis nisi Callimachus? si plus adposcere visus,<br>fit Mimnermus et optivo cognomine crescit.<br>multa fero, ut placem genus irritabile vatum,<br>cum scribo et supplex populi suffragia capto;<br>idem finitis studiis et mente recepta<br>obturem patulas impune legentibus auris.", "st": "2.2"}, {"sp": "N", "t": "Ridentur mala qui componunt carmina; verum<br>gaudent scribentes et se venerantur et ultro,<br>si taceas, laudant quidquid scripsere beati.<br>at qui legitimum cupiet fecisse poema,<br>cum tabulis animum censoris sumet honesti;<br>audebit, quaecumque parum splendoris habebunt<br>et sine pondere erunt et honore indigna ferentur,<br>verba movere loco, quamvis invita recedant<br>et versentur adhuc intra penetralia Vestae;<br>obscurata diu populo bonus eruet atque<br>proferet in lucem speciosa vocabula rerum,<br>quae priscis memorata Catonibus atque Cethegis<br>nunc situs informis premit et deserta vetustas;<br>adsciscet nova, quae genitor produxerit usus.<br>vemens et liquidus puroque simillimus amni<br>fundet opes Latiumque beabit divite lingua;<br>luxuriantia compescet, nimis aspera sano<br>levabit cultu, virtute carentia tollet,<br>ludentis speciem dabit et torquebitur, ut qui<br>nunc Satyrum, nunc agrestem Cyclopa movetur.", "st": "2.2"}, {"sp": "N", "t": "Praetulerim scriptor delirus inersque videri,<br>dum mea delectent mala me vel denique fallant,<br>quam sapere et ringi. fuit haud ignobilis Argis,<br>qui se credebat miros audire tragoedos<br>in vacuo laetus sessor plausorque theatro;<br>cetera qui vitae servaret munia recto<br>more, bonus sane vicinus, amabilis hospes,<br>comis in uxorem, posset qui ignoscere servis<br>et signo laeso non insanire lagoenae,<br>posset qui rupem et puteum vitare patentem.<br>hic ubi cognatorum opibus curisque refectus<br>expulit elleboro morbum bilemque meraco,<br>et redit ad sese: “pol, me occidistis, amici,<br>non servastis,” ait, “cui sic extorta voluptas<br>et demptus per vim mentis gratissimus error.”<br>Nimirum sapere est abiectis utile nugis,<br>et tempestivum pueris concedere ludum,<br>ac non verba sequi fidibus modulanda Latinis,<br>sed verae numerosque modosque ediscere vitae,<br>quocirca mecum loquor haec tacitusque recordor:<br>Si tibi nulla sitim finiret copia lymphae,<br>narrares medicis: quod, quanto plura parasti,<br>tanto plura cupis, nulline faterier audes?<br>si volnus tibi monstrata radice vel herba<br>non fieret levius, fugeres radice vel herba<br>proficiente nihil curarier: audieras, cui<br>rem di donarent, illi decedere pravam<br>stultitiam; et cum sis nihilo sapientior ex quo<br>plenior es, tamen uteris monitoribus isdem?", "st": "2.2"}, {"sp": "N", "t": "At si divitiae prudentem reddere possent,<br>si cupidum timidumque minus te, nempe ruberes,<br>viveret in terris te si quis avarior uno.<br>si proprium est, quod quis libra mercatus et aere est,<br>quaedam, si credis consultis, mancipat usus;<br>qui te pascit ager tuus est, et vilicus Orbi,<br>cum segetes occat tibi mox frumenta daturas,<br>te dominum sentit, das nummos, accipis uvam,<br>pullos, ova, cadum temeti: nempe modo isto<br>paulatim mercaris agrum, fortasse trecentis<br>aut etiam supra nummorum milibus emptum.<br>quid refert, vivas numerato nuper an olim?<br>emptor Aricini quondam Veientis et arvi<br>emptum cenat holus, quamvis aliter putat; emptis<br>sub noctem gelidam lignis calefactat aënum;<br>sed vocat usque suum, qua populus adsita certis<br>limitibus vicina refugit iurgia; tamquam<br>sit proprium quicquam, puncto quod mobilis horae<br>nunc prece, nunc pretio, nunc vi, nunc morte suprema<br>permutet dominos et cedat in altera iura.<br>sic quia perpetuus nulli datur usus, et heres<br>heredem alterius velut unda supervenit undam,<br>quid vici prosunt aut horrea? quidve Calabris<br>saltibus adiecti Lucani, si metit Orcus<br>grandia cum parvis, non exorabilis auro?", "st": "2.2"}, {"sp": "N", "t": "Gemmas, marmor, ebur, Tyrrhena sigilla, tabellas,<br>argentum, vestes Gaetulo murice tinctas<br>sunt qui non habeant, est qui non curat habere,<br>cur alter fratrum cessare et ludere et ungui<br>praeferat Herodis palmetis pinguibus, alter<br>dives et importunus ad umbram lucis ab ortu<br>silvestrem flammis et ferro mitiget agrum,<br>scit Genius, natale comes qui temperat astrum,<br>naturae deus humanae, mortalis in unum<br>quodque caput, voltu mutabilis, albus et ater.<br>utar et ex modico, quantum res poscet, acervo<br>tollam, nec metuam quid de me iudicet heres,<br>quod non plura datis invenerit; et tamen idem<br>scire volam, quantum simplex hilarisque nepoti<br>discrepet et quantum discordet parcus avaro.<br>distat enim, spargas tua prodigus, an neque sumptum<br>invitus facias neque plura parare labores,<br>ac potius, puer ut festis Quinquatribus olim,<br>exiguo gratoque fruaris tempore raptim,<br>pauperies immunda domus procul absit: ego, utrum<br>nave ferar magna an parva, ferar unus et idem.<br>non agimur tumidis velis Aquilone secundo:<br>non tamen adversis aetatem ducimus Austris,<br>viribus, ingenio, specie, virtute, loco, re<br>extremi primorum, extremis usque priores.", "st": "2.2"}, {"sp": "N", "t": "Non es avarus: abi. quid? cetera iam simul isto<br>cum vitio fugere? caret tibi pectus inani<br>ambitione? caret mortis formidine et ira?<br>somnia, terrores magicos, miracula, sagas,<br>nocturnos lemures portentaque Thessala rides?<br>natalis grate numeras? ignoscis amicis?<br>lenior et melior fis accedente senecta?<br>quid te exempta iuvat spinis de pluribus una?<br>vivere si recte nescis, decede peritis,<br>lusisti satis, edisti satis atque bibisti:<br>tempus abire tibi est, ne potum largius aequo<br>rideat et pulset lasciva decentius aetas.", "st": "2.2"}], []);})();
